syntax.pt:
static tipo Nome(tipo parametro)
{
    return valor;
}

static tipo Nome(tipo parametro) => valor;   // só uma expressão

Nome(argumento)   // chamar o método

static void Nome()   // void: não devolve nada

syntax.en:
static type Name(type parameter)
{
    return value;
}

static type Name(type parameter) => value;   // a single expression

Name(argument)   // call the method

static void Name()   // void: returns nothing

example:
static int Triple(int gold) => gold * 3;

static string Greet(string wizard) => "Hello, " + wizard;

static int Loot() => Triple(4);
